<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;
use App\Models\{Product,Category};
use App\Services\Marketing\MarketingTemplateProjects;
use Illuminate\Http\Request;
class MarketingTemplateController extends Controller
{
 private function owner(Request $r,string $permission=\App\Domain\Marketing\MarketingPermission::VIEW):int {abort_unless(\App\Domain\Marketing\MarketingPermission::allows($r->user(),$permission),403);return $r->user()->id;}
 public function entry(Request $r,MarketingTemplateProjects $s){$this->owner($r);$d=$r->validate(['product_id'=>'nullable|integer|exists:products,id']);$p=isset($d['product_id'])?Product::with('category')->find($d['product_id']):null;$selected=$p?['id'=>$p->id,'name'=>$p->title,'category'=>$p->category?->name??'未分类','image'=>$p->images()->orderBy('position')->first()?->path]:null;return response()->view('marketing.workspace.template',['templateBoot'=>['project'=>null,'run'=>null,'template'=>$s->catalog(),'selected_product'=>$selected]]);}
 public function products(Request $r){
  $this->owner($r);$d=$r->validate(['q'=>'nullable|string|max:120','category'=>'nullable|integer|min:1','cursor'=>'nullable|integer|min:0','limit'=>'nullable|integer|min:1|max:10000']);$limit=min(20,$d['limit']??20);
  $query=Product::query()->select(['id','title','handle','category_id','status'])->with(['images'=>fn($q)=>$q->select(['id','product_id','path'])->orderBy('position')->orderBy('id')->limit(1),'category:id,name'])->withCount('images');
  if(!empty($d['q'])){$q=trim($d['q']);$query->where(function($b)use($q){$b->where('title','like','%'.addcslashes($q,'%_\\').'%')->orWhere('handle','like','%'.addcslashes($q,'%_\\').'%')->orWhereHas('variants',fn($v)=>$v->where('sku','like',addcslashes($q,'%_\\').'%'));if(ctype_digit($q))$b->orWhere('id',(int)$q);});}
  if(!empty($d['category']))$query->where('category_id',$d['category']);if(!empty($d['cursor']))$query->where('id','<',$d['cursor']);
  $rows=$query->orderByDesc('id')->limit($limit+1)->get();$more=$rows->count()>$limit;$rows=$rows->take($limit);
  return response()->json(['data'=>$rows->map(fn($p)=>['id'=>$p->id,'name'=>$p->title,'category'=>$p->category?->name??'未分类','status'=>$p->status,'image'=>$p->images->first()?->path,'image_count'=>$p->images_count])->values(),'meta'=>['has_more'=>$more,'next_cursor'=>$more?$rows->last()?->id:null],'categories'=>Category::orderBy('name')->limit(100)->get(['id','name'])]);
 }
 public function create(Request $r,MarketingTemplateProjects $s){
  $this->owner($r,\App\Domain\Marketing\MarketingPermission::EDIT);$allowed=['request_id','product_id','template_id','language','formats','narration','subtitles','goal','request','duration'];abort_if(array_diff(array_keys($r->all()),$allowed),422,'请求含不支持的字段。');
  $d=$r->validate(['request_id'=>'required|uuid','product_id'=>'required|integer|exists:products,id','template_id'=>'required|in:'.MarketingTemplateProjects::ID,'language'=>'required|in:English,zh-MY','formats'=>'required|array|list|min:1|max:2','formats.*'=>'required|distinct|in:landscape,portrait','narration'=>'required|boolean','subtitles'=>'required|boolean','goal'=>'required|in:introduction,awareness,details','request'=>'nullable|string|max:1500','duration'=>'required|in:15']);
  abort_if($d['subtitles']&&!$d['narration'],422,'当前模板字幕需要配合口播；可同时关闭。');
  [$p,$new]=$s->create($r->user(),$d);return response()->json($s->view($p)+['url'=>route('marketing.workspace.show',['project'=>$p->id,'screen'=>'guided'])],$new?201:200);
 }
 public function status(Request $r,string $project,MarketingTemplateProjects $s){return response()->json($s->view($s->owned($project,$this->owner($r))))->header('Cache-Control','private, no-store');}
 public function planningQuote(Request $r,string $project,MarketingTemplateProjects $s,\App\Services\Marketing\MarketingTemplatePlanningConsent $consent){$p=$s->owned($project,$this->owner($r));abort_if(array_diff(array_keys($r->all()),['version']),422);$d=$r->validate(['version'=>'required|integer|min:1']);return response()->json(['quote'=>$consent->quote($p,$d['version'])])->header('Cache-Control','private, no-store');}
 public function planningAuthorize(Request $r,string $project,MarketingTemplateProjects $s,\App\Services\Marketing\MarketingTemplatePlanningConsent $consent){$p=$s->owned($project,$this->owner($r,\App\Domain\Marketing\MarketingPermission::APPROVE_COST));abort_if(array_diff(array_keys($r->all()),['version','token','consent','rights_confirmed']),422);$d=$r->validate(['version'=>'required|integer|min:1','token'=>'required|string|max:16000','consent'=>'required|accepted','rights_confirmed'=>'required|accepted']);$consent->authorize($p,$d['version'],$d['token']);return response()->json($s->view($p->fresh()));}
 public function revisionQuote(Request $r,string $project,MarketingTemplateProjects $s,\App\Services\Marketing\MarketingTemplateRevisionConsent $consent){$p=$s->owned($project,$this->owner($r,\App\Domain\Marketing\MarketingPermission::EDIT));$this->owner($r,\App\Domain\Marketing\MarketingPermission::APPROVE_COST);$d=$r->validate(['version'=>'required|integer','run_id'=>'required|uuid','request'=>'required|string|max:1500']);return response()->json(['quote'=>$consent->quote($p,$d)])->header('Cache-Control','private, no-store');}
 public function revisionAuthorize(Request $r,string $project,MarketingTemplateProjects $s,\App\Services\Marketing\MarketingTemplateRevisionConsent $consent){$p=$s->owned($project,$this->owner($r,\App\Domain\Marketing\MarketingPermission::EDIT));$this->owner($r,\App\Domain\Marketing\MarketingPermission::APPROVE_COST);$d=$r->validate(['version'=>'required|integer','token'=>'required|string|max:16000','consent'=>'required|accepted','rights_confirmed'=>'required|accepted']);$consent->authorize($p,$d);return response()->json($s->view($p->fresh()));}
 public function localCopy(Request $r,string $project,MarketingTemplateProjects $s,\App\Services\Marketing\MarketingTemplateLocalRevision $local){$p=$s->owned($project,$this->owner($r,\App\Domain\Marketing\MarketingPermission::EDIT));abort_if(array_diff(array_keys($r->all()),['version','run_id','request_id','copy','confirmed']),422);$d=$r->validate(['version'=>'required|integer','run_id'=>'required|uuid','request_id'=>'required|uuid','copy'=>'required|array:hook,benefit,support,cta|min:1','copy.*'=>'required|string|max:120','confirmed'=>'required|accepted']);$local->create($p,$d);return response()->json($s->view($p->fresh()));}
 public function write(Request $r,string $project,string $action,MarketingTemplateProjects $s,\App\Services\Marketing\MarketingTemplateWorkflow $w){
  $p=$s->owned($project,$this->owner($r,\App\Domain\Marketing\MarketingPermission::EDIT));if(in_array($action,['plan','produce','revise'],true))$this->owner($r,\App\Domain\Marketing\MarketingPermission::APPROVE_COST);
  $rules=match($action){'refresh-quote'=>['version'=>'required|integer|min:1','run_id'=>'required|uuid'],'brief'=>['version'=>'required|integer|min:1','goal'=>'required|in:introduction,awareness,details','audience'=>'nullable|string|max:500','request'=>'nullable|string|max:1500'],'plan'=>['version'=>'required|integer|min:1','request_id'=>'required|uuid'],'produce'=>['version'=>'required|integer|min:1','run_id'=>'required|uuid','quote_digest'=>'required|string|size:64','consent'=>'required|accepted'],'revise'=>['version'=>'required|integer|min:1','run_id'=>'required|uuid','request_id'=>'required|uuid','request'=>'required|string|max:1500']};
  abort_if(array_diff(array_keys($r->all()),array_keys($rules)),422);$d=$r->validate($rules);
  match($action){'refresh-quote'=>$w->refreshQuote($p,$d),'brief'=>$w->brief($p,$d),'plan'=>$w->start($p,$d),'produce'=>$w->produce($p,$d),'revise'=>$w->start($p,$d,\App\Models\MarketingTemplateRun::where('project_id',$p->id)->findOrFail($d['run_id']))};
  return response()->json($s->view($p->fresh()));
 }
 public function media(Request $r,string $project,string $run,string $format,MarketingTemplateProjects $s){$p=$s->owned($project,$this->owner($r));$record=\App\Models\MarketingTemplateRun::where('project_id',$p->id)->where('status','completed')->findOrFail($run);$row=$record->result['formats'][$format]??null;abort_unless($row,404);$path=app(\App\Services\Marketing\MarketingVideoFiles::class)->file($row['path'],$row['sha256']);return $r->boolean('download')?response()->download($path,$p->name.'-'.$format.'.mp4'):response()->file($path,['Content-Type'=>'video/mp4','Cache-Control'=>'private, no-store']);}
}
